/// Dive regions drawn from Global's records by where each species occurs (owner decision,
/// 2026-10-26). A species belongs to every region it occurs in. Membership is generated by
/// Tools/FishBaseIntake/derive_regions.py from Global's FAO areas and FishBase country
/// records; Release still shows only approved records.
enum GlobalSubregions {
    static let definitions = [
        derived(.tropicalAtlantic, "TropicalAtlantic"),
        derived(.indoPacific, "IndoPacific"),
        derived(.pacificCoast, "PacificCoast"),
        derived(.mediterranean, "Mediterranean"),
    ]

    private static func derived(_ id: OfflineIdentificationPackID, _ directory: String) -> RegionCatalogDefinition {
        RegionCatalogDefinition(id: id, resourceDirectory: directory,
                                availableInRelease: GlobalRegion.definition.availableInRelease,
                                derivedFrom: GlobalRegion.definition.id)
    }
}
